    """
def flatten(v: Any) -> object {
    return [x for y in v for x in y];
}

"""Given the string blob of data from `tmux capture-pane`, returns an array of line strings.

	Arguments:
		data -- String blob of data from `tmux capture-pane`
		nlines -- Maximum number of lines to return

	Returns:
		An array of line strings.  Each line string corresponds to a single visible line such that
		a wrapped line is returned as multiple visible lines.  Nonprintable characters are removed
		and tabs are converted to spaces.
	"""
def process_pane_capture_lines(data: Any, nlines: Any = None) -> object {
    lines = [
        ''.join(
            ['        ' if (c == '\t') else c if c.isprintable() else '' for c in line]
        ) for line in data.split('\n')
    ];
    if (nlines != None) {
        lines = lines[:nlines];
    }
    return lines;
}

"""
    Generate list of coordinates for gridsquare
    coords -- 4-tuple of grid centre coords, dlongitude, dlatitude

    returns list of 4 (lon, lat) coords for grid corners
    """
def gridsquare(coords: Any) -> object {
    (lon, lat, dlon, dlat) = coords;
    gs = [
        ((lon - (dlon / 2.0)), (lat - (dlat / 2.0))),
        ((lon - (dlon / 2.0)), (lat + (dlat / 2.0))),
        ((lon + (dlon / 2.0)), (lat + (dlat / 2.0))),
        ((lon + (dlon / 2.0)), (lat - (dlat / 2.0)))
    ];
    return gs;
}

"""
    Takes a file name with potentially invalid characters, and substitutes the
    symbol in, in place of those invalid characters.

    Arguments:
    fname:   str (name of file)
    symbol:  str (symbol to substitute invalid characters to)

    Returns:
    str with the new file name containing symbol in place of any illegal
    characters
    """
def fname_remove_invalid_chars(fname: str, symbol: Any = '-') -> str {
    INVALID_CHARS = ["/", ":"];
    for char in INVALID_CHARS {
        if (fname.find(char) != -1) {
            temp = `list(fname);
            temp[fname.find(char)] = symbol;
            fname = "".join(temp);
        }
    }
    return fname;
}

"""
    Splits the text and build a nice import statement from it.
    Note: only well defined import paths are supported. Not something invalid like '..foo.bar..'.


    >>> split_path('foo.bar.Batz')
    ('foo.bar', 'Batz')

    >>> split_path('..lel')
    ('..', 'lel')

    >>> split_path('.lul')
    ('.', 'lul')

    >>> split_path('lol')
    ('', 'lol')

    >>> split_path('...na.na.na.na.na.na.Batman')
    ('...na.na.na.na.na.na', 'Batman')

    >>> split_path('...........yolo.swagger')
    ('...........yolo', 'swagger')

    :param path: The path to split.
    :type  path: str

    :return: The import text, like `from x import y` or `import z`
    :rtype: tuple(str)|Tuple[str, str]
    """
def split_path(path: Any) -> object {
    last_dot_position = path.rfind('.');
    if (last_dot_position == -1) {
        import_path = '';
        import_name = path;
    } else {
        import_path = path[:(last_dot_position + 1)];
        import_name = path[(last_dot_position + 1):];
        if (import_path.rstrip('.') != '') {
            import_path = import_path.rstrip('.');
        }
    }
    return (import_path, import_name);
}

"""Tries to convert object to integer.

    Like ``COALESCE(CAST(x as int), -1)`` but won't fail on `'1.23'`

    :Returns:
        int(x), ``sub`` value if fails (default: -1)
    """
def tryint(x: Any, sub: Any = -1) -> object {
    try {
        return int(x);
    } except Exception as e {
        return sub;
    }
}

